using System.Data;using Microsoft.Data.SqlClient;using TransPort.Api.Configuration;using TransPort.Api.Modules.Produccion.DTOs;using TransPort.Api.Modules.Shared.DTOs;using TransPort.Api.Modules.Shared.Repositories;
namespace TransPort.Api.Modules.Produccion.Repositories;
public sealed class ProduccionRepository(ISqlConnectionFactory connections):IProduccionRepository
{
 public async Task<IReadOnlyList<ProduccionListadoDto>>ListarAsync(string?estado,int?sedeId,DateTime?desde,DateTime?hasta,AlcanceProduccion a,CancellationToken ct){var x=new List<ProduccionListadoDto>();await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_leer_listado");Scope(c,a);c.Parameters.Add("@Estado",SqlDbType.NVarChar,30).Value=Db(T(estado));c.Parameters.Add("@SedeId",SqlDbType.Int).Value=Db(sedeId);c.Parameters.Add("@FechaDesde",SqlDbType.Date).Value=Db(desde?.Date);c.Parameters.Add("@FechaHasta",SqlDbType.Date).Value=Db(hasta?.Date);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(Listado(r));return x;}
 public async Task<ProduccionDetalleDto?>ObtenerAsync(long id,AlcanceProduccion a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_leer_por_id");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var x=new ProduccionDetalleDto(r.Int64("ProduccionOrdenId"),r.Int32("SedeId"),r.Text("Sede"),r.Int32("ArticuloEntradaId"),r.Text("CodigoEntrada"),r.Text("ArticuloEntrada"),r.Text("UnidadEntrada"),r.Int32("ArticuloSalidaId"),r.Text("CodigoSalida"),r.Text("ArticuloSalida"),r.Text("UnidadSalida"),r.Date("FechaPlanificada"),D(r,"CantidadEntrada"),D(r,"CantidadSalidaPlanificada"),ND(r,"CantidadSalidaReal"),ND(r,"CantidadMerma"),ND(r,"CostoUnitario"),r.Text("Estado"),r.Int32("ResponsableUsuarioId"),r.Text("Responsable"),r.NullableText("Observacion"),r.Date("FechaCreacion"),r.NullableDate("FechaModificacion"),[],[]);var etapas=new List<ProduccionEtapaDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))etapas.Add(new(r.Int64("ProduccionEtapaId"),r.Int32("Secuencia"),r.Text("Nombre"),r.Text("Estado"),r.NullableDate("FechaInicio"),r.NullableDate("FechaFin"),r.NullableText("Observacion")));var historial=new List<ProduccionHistorialDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))historial.Add(new(r.Int64("ProduccionHistorialId"),r.Int32("UsuarioId"),r.Text("NombreUsuario"),r.NullableText("EstadoAnterior"),r.Text("EstadoNuevo"),r.NullableText("Comentario"),r.Date("Fecha")));return x with{Etapas=etapas,Historial=historial};}
 public async Task<ProduccionOpcionesDto>OpcionesAsync(AlcanceProduccion a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_leer_opciones");Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);var s=await Cats(r,ct);var arts=await r.NextResultAsync(ct)?await Cats(r,ct):[];return new(s,arts);}
 public async Task<long>CrearAsync(CrearProduccionRequest x,AlcanceProduccion a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_crear");c.Parameters.Add("@SedeId",SqlDbType.Int).Value=x.SedeId;c.Parameters.Add("@ArticuloEntradaId",SqlDbType.Int).Value=x.ArticuloEntradaId;c.Parameters.Add("@ArticuloSalidaId",SqlDbType.Int).Value=x.ArticuloSalidaId;c.Parameters.Add("@FechaPlanificada",SqlDbType.Date).Value=x.FechaPlanificada.Date;Dec(c,"@CantidadEntrada",x.CantidadEntrada,18,3);Dec(c,"@CantidadSalidaPlanificada",x.CantidadSalidaPlanificada,18,3);c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(x.Observacion));Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}
 public async Task<bool>CambiarEstadoAsync(long id,CambiarEstadoProduccionRequest x,AlcanceProduccion a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_actualizar_estado");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@Estado",SqlDbType.NVarChar,30).Value=x.Estado.Trim();NullableDec(c,"@CantidadSalidaReal",x.CantidadSalidaReal,18,3);NullableDec(c,"@CantidadMerma",x.CantidadMerma,18,3);NullableDec(c,"@CostoUnitario",x.CostoUnitario,18,2);c.Parameters.Add("@Comentario",SqlDbType.NVarChar,500).Value=Db(T(x.Comentario));Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 public async Task<bool>CompletarEtapaAsync(long id,long etapaId,string?observacion,AlcanceProduccion a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_completar_etapa");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@EtapaId",SqlDbType.BigInt).Value=etapaId;c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(observacion));Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 public async Task<bool>EliminarAsync(long id,int u,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_produccion_eliminar");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=u;return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 private static ProduccionListadoDto Listado(SqlDataReader r)=>new(r.Int64("ProduccionOrdenId"),r.Int32("SedeId"),r.Text("Sede"),r.Int32("ArticuloEntradaId"),r.Text("CodigoEntrada"),r.Text("ArticuloEntrada"),r.Text("UnidadEntrada"),r.Int32("ArticuloSalidaId"),r.Text("CodigoSalida"),r.Text("ArticuloSalida"),r.Text("UnidadSalida"),r.Date("FechaPlanificada"),D(r,"CantidadEntrada"),D(r,"CantidadSalidaPlanificada"),ND(r,"CantidadSalidaReal"),ND(r,"CantidadMerma"),ND(r,"CostoUnitario"),r.Text("Estado"),r.Text("Responsable"),r.Date("FechaCreacion"),r.NullableText("EtapaActual"));
 private static async Task<IReadOnlyList<CatalogoDto>>Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}private static void Scope(SqlCommand c,AlcanceProduccion a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static SqlCommand P(SqlConnection c,string n)=>new(n,c){CommandType=CommandType.StoredProcedure};private static object Db(object?x)=>x??DBNull.Value;private static string?T(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static decimal D(SqlDataReader r,string n)=>r.GetDecimal(r.GetOrdinal(n));private static decimal?ND(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetDecimal(i);}private static void Dec(SqlCommand c,string n,decimal v,byte p,byte s){var x=c.Parameters.Add(n,SqlDbType.Decimal);x.Precision=p;x.Scale=s;x.Value=v;}private static void NullableDec(SqlCommand c,string n,decimal?v,byte p,byte s){var x=c.Parameters.Add(n,SqlDbType.Decimal);x.Precision=p;x.Scale=s;x.Value=Db(v);}
}
